#include <assert.h>
#include "../kernel/sync_core.h"
int main(void){sync_tracker_t t={0};int a,b,c;assert(sync_core_before_lock(&t,(uintptr_t)&a,1)==SYNC_OK);assert(sync_core_push(&t,(uintptr_t)&a,1)==SYNC_OK);assert(sync_core_before_lock(&t,(uintptr_t)&a,2)==SYNC_RECURSIVE);assert(sync_core_before_lock(&t,(uintptr_t)&b,1)==SYNC_ORDER_VIOLATION);assert(sync_core_before_lock(&t,(uintptr_t)&b,2)==SYNC_OK);assert(sync_core_push(&t,(uintptr_t)&b,2)==SYNC_OK);assert(sync_core_pop(&t,(uintptr_t)&a)==SYNC_NOT_LIFO);assert(sync_core_push(&t,(uintptr_t)&c,3)==SYNC_OK);assert(sync_core_pop(&t,(uintptr_t)&c)==SYNC_OK);assert(sync_core_pop(&t,(uintptr_t)&b)==SYNC_OK);assert(sync_core_pop(&t,(uintptr_t)&a)==SYNC_OK);for(unsigned i=0;i<SYNC_MAX_LOCK_DEPTH;i++)assert(sync_core_push(&t,(uintptr_t)(i+1),(uint8_t)(i+1))==SYNC_OK);assert(sync_core_before_lock(&t,99,2)==SYNC_DEPTH_EXCEEDED);return 0;}
